namespace RonSijm.FluidHumidifier.Factories.PCS;

public class ComputeNodeGroupFactory(string resourceName = null, Action<Humidifier.PCS.ComputeNodeGroup> factoryAction = null) : ResourceFactory<Humidifier.PCS.ComputeNodeGroup>(resourceName)
{

    internal List<InnerComputeNodeGroupInstanceConfigFactory> InstanceConfigsFactories { get; set; } = [];

    internal InnerComputeNodeGroupSpotOptionsFactory SpotOptionsFactory { get; set; }

    internal InnerComputeNodeGroupSlurmConfigurationFactory SlurmConfigurationFactory { get; set; }

    internal InnerComputeNodeGroupScalingConfigurationFactory ScalingConfigurationFactory { get; set; }

    internal InnerComputeNodeGroupCustomLaunchTemplateFactory CustomLaunchTemplateFactory { get; set; }

    protected override Humidifier.PCS.ComputeNodeGroup Create()
    {
        var computeNodeGroupResult = CreateComputeNodeGroup();
        factoryAction?.Invoke(computeNodeGroupResult);

        return computeNodeGroupResult;
    }

    private Humidifier.PCS.ComputeNodeGroup CreateComputeNodeGroup()
    {
        var computeNodeGroupResult = new Humidifier.PCS.ComputeNodeGroup
        {
            GivenName = InputResourceName,
        };

        return computeNodeGroupResult;
    }
    public override void CreateChildren(Humidifier.PCS.ComputeNodeGroup result)
    {
        base.CreateChildren(result);

        result.InstanceConfigs = InstanceConfigsFactories.Any() ? InstanceConfigsFactories.Select(x => x.Build()).ToList() : null;
        result.SpotOptions ??= SpotOptionsFactory?.Build();
        result.SlurmConfiguration ??= SlurmConfigurationFactory?.Build();
        result.ScalingConfiguration ??= ScalingConfigurationFactory?.Build();
        result.CustomLaunchTemplate ??= CustomLaunchTemplateFactory?.Build();
    }

} // End Of Class

